<script setup>
import { Head, useForm, usePage } from '@inertiajs/vue3';
import { Phone, Mail, MapPin, Send, Upload, CheckCircle2 } from '@lucide/vue';
import { computed } from 'vue';
import StorefrontLayout from './StorefrontLayout.vue';
const page=usePage();
const settings=computed(()=>page.props.storeSettings || {});
const companyPhone=computed(()=>settings.value.phone_one || settings.value.phone_two);
const companyEmail=computed(()=>settings.value.email_one || settings.value.email_two);
const form=useForm({name:'',email:'',phone:'',address:'',years_of_experience:'',expected_salary:'',motivation:'',attachment:null});
const fields=[['name','Full name','text'],['email','Email address','email'],['phone','Phone number','tel'],['years_of_experience','Years of Experience','number'],['expected_salary','Expected Salary (BDT)','number']];
function submit(){form.post('/career',{forceFormData:true,preserveScroll:true,onSuccess:()=>{form.reset();if(document.querySelector('#career_attachment'))document.querySelector('#career_attachment').value='';}});}
</script>
<template>
    <Head title="Career | FARBO"/><StorefrontLayout><main class="career-page"><div class="career-shell">
        <header class="career-heading"><span>GROW WITH FARBO</span><h1>Build your next chapter with us.</h1><p>Bring your experience, ideas and ambition. Tell us a little about yourself and how you would like to contribute to our team.</p></header>
        <div class="career-grid"><aside class="career-intro"><div class="company-logo" v-if="settings.header_logo || settings.footer_logo"><img :src="settings.header_logo || settings.footer_logo" :alt="settings.company_name || 'FARBO'"/></div><h2>{{settings.company_name || 'FARBO'}}</h2><p v-if="settings.footer_description">{{settings.footer_description}}</p><div class="company-contacts"><a v-if="companyPhone" :href="'tel:'+companyPhone"><Phone :size="18"/><div><span>PHONE</span><strong>{{companyPhone}}</strong></div></a><a v-if="companyEmail" :href="'mailto:'+companyEmail"><Mail :size="18"/><div><span>EMAIL</span><strong>{{companyEmail}}</strong></div></a><div v-if="settings.address" class="company-address"><MapPin :size="18"/><div><span>ADDRESS</span><strong>{{settings.address}}</strong></div></div></div></aside>
        <section class="career-form-card"><div class="form-heading"><span>YOUR APPLICATION</span><h2>Let’s get to know you</h2><p>Fields marked * are required.</p></div>
        <div v-if="page.props.flash?.success" class="career-success" role="status"><CheckCircle2 :size="22"/><p>{{ page.props.flash.success }}</p></div>
        <form @submit.prevent="submit" class="career-form">
            <label v-for="[key,label,type] in fields" :key="key"><span>{{label}} <b>*</b></span><input :id="'career_'+key" v-model="form[key]" :type="type" :min="type==='number'?0:undefined" :max="key==='years_of_experience'?80:(key==='expected_salary'?99999999:undefined)" :step="key==='years_of_experience'?'0.1':(type==='number'?'0.01':undefined)" :maxlength="key==='name'?160:(key==='phone'?40:255)" required :aria-invalid="!!form.errors[key]"/><small v-if="form.errors[key]">{{form.errors[key]}}</small></label>
            <label class="full"><span>Address <b>*</b></span><textarea v-model="form.address" rows="2" maxlength="2000" required :aria-invalid="!!form.errors.address"/><small v-if="form.errors.address">{{form.errors.address}}</small></label>
            <label class="full"><span>Why do you want to join us? <b>*</b></span><textarea v-model="form.motivation" rows="5" maxlength="20000" placeholder="Tell us about your strengths, interests and what you would bring to the team." required :aria-invalid="!!form.errors.motivation"/><small v-if="form.errors.motivation">{{form.errors.motivation}}</small></label>
            <label class="full attachment-field"><span><Upload :size="17"/>CV / supporting attachment <em>Optional</em></span><input id="career_attachment" type="file" accept=".pdf,.doc,.docx,.txt,.rtf,.jpg,.jpeg,.png,.odt" @change="form.attachment=$event.target.files[0] || null"/><p>PDF, Word, text or image · Maximum 10 MB</p><small v-if="form.errors.attachment">{{form.errors.attachment}}</small></label>
            <div class="full form-actions"><p>Your information will be used to review your application.</p><button :disabled="form.processing" type="submit"><Send :size="17"/>{{form.processing?'Submitting…':'Submit application'}}</button></div>
        </form></section></div>
    </div></main></StorefrontLayout>
</template>
