e-height:1.8}.career-form input:focus,.career-form textarea:focus{outline:2px solid #c2d5e8;outline-offset:1px;background:white}.career-form small{color:#b42318;font-size:11px}.full{grid-column:1/-1}.attachment-field{padding:20px;border:1px dashed #c9d8e6;border-radius:12px;background:#f9fbfd}.attachment-field>span{display:flex;align-items:center;gap:8px}.attachment-field em{font-size:10px;color:#8c99a7;font-style:normal;margin-left:auto}.attachment-field input{border:0;padding:0;background:transparent}.attachment-field p{font-size:10px;color:#8090a2}.form-actions{display:flex;gap:18px;align-items:center;justify-content:space-between;padding-top:8px}.form-actions p{font-size:10px;color:#8996a5;line-height:1.7;max-width:240px}.form-actions button{display:flex;align-items:center;justify-content:center;gap:9px;background:#0b2a5b;color:white;padding:14px 20px;border-radius:10px;font-size:12px;font-weight:600;white-space:nowrap}.form-actions button:disabled{opacity:.6;cursor:wait}.career-success{display:flex;gap:12px;align-items:center;padding:16px;border:1px solid #cde4d6;background:#f1faf5;color:#286349;font-size:12px;line-height:1.7;border-radius:12px;margin-bottom:24px}.career-success svg{flex-shrink:0}@media(max-width:850px){.career-grid{grid-template-columns:1fr}.career-intro{border-right:0;border-bottom:1px solid #dfe8f1}}@media(max-width:540px){.career-page{padding:32px 16px 48px}.career-form-card{padding:24px 20px}.career-form{grid-template-columns:1fr}.form-actions{flex-direction:column;align-items:stretch}.form-actions p{max-width:none}}
